fn get_min_val(a: &Vec<i8>) -> i8 {
    *a.iter().min().unwrap() // Get the minimum value from the array
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    *a.iter().max().unwrap() // Get the maximum value from the array
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    assert!(q >= 0 && q <= 100, "Quantile percentage must be between 0 and 100");

    let min_val = get_min_val(&a);
    let max_val = get_max_val(&a);

    if q == 0 {
        return min_val; // Return minimum for 0% quantile
    } else if q == 100 {
        return max_val; // Return maximum for 100% quantile
    }

    // Calculate the index for the quantile
    let n = a.len() as f64;
    let quantile_index = ((q as f64 / 100.0) * (n - 1.0)).round() as usize;

    // Sort the array to find the quantile value
    let mut sorted_a = a.clone();
    sorted_a.sort();

    sorted_a[quantile_index] // Return the quantile value
}